const text = items[0].json.output;

const lines = text.split('\n');

const results = [];

let current = {};

for (const line of lines) {

  // Extract Title
  if (line.startsWith('Title:')) {
    current.title = line.replace('Title:', '').trim();
  }

  // Extract ISO
  else if (line.startsWith('ISO:')) {
    current.iso = line.replace('ISO:', '').trim();
  }

  // Extract Query
  else if (line.startsWith('Query:')) {
    current.query = line
      .replace('Query:', '')
      .trim()
      .replace(/^`|`$/g, '');

    // Push completed object
    results.push({
      json: {
        title: current.title || '',
        iso: current.iso || '',
        query: current.query || '',
      }
    });

    // Reset current object
    current = {};
  }
}

return results;

// Get all incoming items
const items = $input.all();

// Build the array
const startUrls = items.map((item, index) => {
  return {
    url: item.json.URL,
    id: (index + 1).toString()
  };
});

// Return as ONE item with the array inside
return [
  {
    json: {
      startUrls
    }
  }
];

// Get all input items
const items = $input.all();

// List of common company suffixes to remove
const suffixesRegex = /\b(incorporated|inc|llc|l\.l\.c|ltd|l\.t\.d|lp|l\.p|corp|corporation|co|company)\b\.?,?/gi;

return items.map(item => {
    let rawName = item.json.title || item.json || "";

    // STEP 1: Remove LinkedIn text and extra separators
    let cleanedName = rawName
        .replace(/\s*[-|]\s*LinkedIn$/i, "")  // remove "- LinkedIn" or "| LinkedIn"
        .trim();

    // STEP 2: Remove company suffixes
    let simpleName = cleanedName
        .replace(suffixesRegex, "")
        .replace(/\s{2,}/g, " ") // remove extra spaces
        .trim();

    return {
        json: {
            original: rawName,
            cleaned_name: cleanedName,
            simple_name: simpleName
        }
    };
});
